for(int rev: new int[] {1,-1}) for(int offset=0;offset<5;offset++){double[] px=new double[6],py=new double[6]; for(int i=0;i<6;i++) {int v=Math.floorMod(offset+rev*i,5);px[i]=xs[v];py[i]=ys[v];} for(var t:Tessellator.tessellate(new Polygon(py,px),true)){var bytes=new byte[28];ShapeField.encodeTriangle(bytes,t.getEncodedY(0),t.getEncodedX(0),t.isEdgefromPolygon(0),t.getEncodedY(1),t.getEncodedX(1),t.isEdgefromPolygon(1),t.getEncodedY(2),t.getEncodedX(2),t.isEdgefromPolygon(2));var d=new ShapeField.DecodedTriangle();ShapeField.decodeTriangle(bytes,d);if(d.type==ShapeField.DecodedTriangle.TYPE.LINE && d.ab==false)System.out.println("rev="+rev+" offset="+offset+" "+t+" => "+d);}}
/exit
EOF

patch -p1 <<'PATCH'
--- a/lucene/core/src/test/org/apache/lucene/document/BaseShapeEncodingTestCase.java
+++ b/lucene/core/src/test/org/apache/lucene/document/BaseShapeEncodingTestCase.java
@@ -638,6 +638,55 @@
     };
   }

+  public void testCollapsedTriangleEdgeFlags() {
+    int ax = encodeX(0);
+    int ay = encodeY(0);
+    byte[] bytes = new byte[7 * ShapeField.BYTES];
+    ShapeField.DecodedTriangle decoded = new ShapeField.DecodedTriangle();
+    for (int[] endpoint :
+        new int[][] {
+          {encodeX(2), encodeY(0)},
+          {encodeX(0), encodeY(2)},
+          {encodeX(2), encodeY(2)}
+        }) {
+      for (boolean fromShape : new boolean[] {false, true}) {
+        for (int i = 0; i < 3; i++) {
+          int[] x = {ax, ax, ax};
+          int[] y = {ay, ay, ay};
+          x[i] = endpoint[0];
+          y[i] = endpoint[1];
+          // Give the collapsed edge the opposite flag from the two retained edges.
+          boolean ab = i == 2 ? !fromShape : fromShape;
+          boolean bc = i == 0 ? !fromShape : fromShape;
+          boolean ca = i == 1 ? !fromShape : fromShape;
+          ShapeField.encodeTriangle(
+              bytes,
+              y[0],
+              x[0],
+              ab,
+              y[1],
+              x[1],
+              bc,
+              y[2],
+              x[2],
+              ca);
+          ShapeField.decodeTriangle(bytes, decoded);
+          assertEquals(ShapeField.DecodedTriangle.TYPE.LINE, decoded.type);
+          assertEquals(ax, decoded.aX);
+          assertEquals(ay, decoded.aY);
+          assertEquals(endpoint[0], decoded.bX);
+          assertEquals(endpoint[1], decoded.bY);
+          assertEquals(ax, decoded.cX);
+          assertEquals(ay, decoded.cY);
+          assertEquals(fromShape, decoded.ab);
+        }
+      }
+    }
+  }
+
   public void testDegeneratedTriangle() {
PATCH
./gradlew --offline :lucene:core:test --tests org.apache.lucene.document.TestLatLonShapeEncoding.testCollapsedTriangleEdgeFlags --tests org.apache.lucene.document.TestXYShapeEncoding.testCollapsedTriangleEdgeFlags

